package com.example.orderprocessing.controller;
import com.example.orderprocessing.dto.OrderRequest; import com.example.orderprocessing.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class DashboardController {private final OrderService orders; private final ProductService products; public DashboardController(OrderService orders,ProductService products){this.orders=orders;this.products=products;} @GetMapping("/dashboard/summary") public Object summary(){return orders.summary();} @GetMapping("/dashboard/orders") public Object dashboardOrders(){return orders.all().stream().map(orders::orderView).toList();} @GetMapping("/dashboard/inventory") public Object inventory(){return products.all();} @PostMapping("/simulation/orders") public Object simulate(@Valid @RequestBody OrderRequest request,@RequestParam(defaultValue="20") int numberOfOrders){return orders.simulate(request,numberOfOrders);} @GetMapping("/health") public Object health(){return java.util.Map.of("status","UP","workers","5 core / 10 max","locking","PESSIMISTIC_WRITE");} }
